import{c as t,Q as a,j as n,m as i}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"Learning from Synthetic Data without Model Collapse in Iterative Instruction Tuning","description":"","frontmatter":{"url":"https://arxiv.org/abs/2607.17043","title":"Learning from Synthetic Data without Model Collapse in Iterative Instruction Tuning","archived_date":"2026-07-31T00:00:00.000Z","arxiv_id":2607.17043,"authors":["Xiaonan Luo","Yue Huang","Kehan Guo","Ping He","Chuan Zou","Ting Hua","Xiangliang Zhang"],"domain":"model-collapse-recursive-training","published_date":"2026-07-19T00:00:00.000Z","source_routine":"routine-e"},"headers":[],"relativePath":"research/papers/2026-07-31-model-collapse-kite-instruction-tuning-2607-17043.md","filePath":"research/papers/2026-07-31-model-collapse-kite-instruction-tuning-2607-17043.md","lastUpdated":1785909234000}'),o={name:"research/papers/2026-07-31-model-collapse-kite-instruction-tuning-2607-17043.md"};function r(l,e,s,c,u,d){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="learning-from-synthetic-data-without-model-collapse-in-iterative-instruction-tuning" tabindex="-1">Learning from Synthetic Data without Model Collapse in Iterative Instruction Tuning <a class="header-anchor" href="#learning-from-synthetic-data-without-model-collapse-in-iterative-instruction-tuning" aria-label="Permalink to &quot;Learning from Synthetic Data without Model Collapse in Iterative Instruction Tuning&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>本文處理語言模型在遞增比例合成資料上訓練導致的 model collapse，核心觀察是：崩潰不只是單純的整體效能下降，而會呈現「能力極化（polarization of competence）」——合成訓練資料會強化模型本來就強的能力，同時讓本來就弱的能力進一步退化。這把 model collapse 從單一純量指標問題重新描述為能力分佈形狀的問題。</p><p>作者提出 KITE（Knowledge-boundary Instruction Tuning via Exploration），一個結合「失敗引導的資料生成」與「邊界感知的不確定性篩選」的兩階段方法：優先在模型現有失敗處取樣，並用不確定性篩選過濾低價值合成樣本。在多個資料集與開源語言模型上的測試顯示，相較其他合成資料訓練方法，KITE 展現更一致的改善，對「每一代都該超越前一代」的迭代式模型開發特別有價值。</p><h2 id="為何屬「新領域」" tabindex="-1">為何屬「新領域」 <a class="header-anchor" href="#為何屬「新領域」" aria-label="Permalink to &quot;為何屬「新領域」&quot;">​</a></h2><p>本文的「能力極化」現象刻畫與 KITE 的失敗引導/邊界篩選配方是本次收錄三篇中最貼近實務配方層的一篇，與 workspace 既有覆蓋（continual learning 候選已被本輪排除、machine-unlearning）機制不同——本文談的是合成資料比例遞增下的資料品質退化與應對配方，非知識更新或刻意遺忘。<code>polarization of competence</code>／<code>KITE</code> 於全庫 0 命中。</p>',6)])])}const m=t(o,[["render",r]]);export{h as __pageData,m as default};
